import main, random
from fractions import Fraction

def indep_term(t, rows, bind, fmap):
    if 'aggregate' in t:
        idx=fmap[t['field']]['index']
        vs=[rows[o][idx] for o in range(t['from'],t['to']+1)]
        op=t['aggregate']
        if op=='sum': return Fraction(sum(vs))
        if op=='mean': return Fraction(sum(vs),len(vs))
        if op=='min': return Fraction(min(vs))
        return Fraction(max(vs))
    if 'field' in t:
        idx=fmap[t['field']]['index']
        off=bind if t['at']=='$' else t['at']
        return rows[off][idx]
    if 'const' in t:
        return t['const']
    if 'scale' in t:
        return t['scale']*indep_term(t['term'],rows,bind,fmap)
    return indep_term(t['add'][0],rows,bind,fmap)+indep_term(t['add'][1],rows,bind,fmap)

def indep_cmp(c,rows,bind,fmap):
    l=indep_term(c['left'],rows,bind,fmap); r=indep_term(c['right'],rows,bind,fmap)
    op=c['cmp']
    return {'eq':l==r,'ne':l!=r,'lt':l<r,'le':l<=r,'gt':l>r,'ge':l>=r}[op]

def indep_atom(a,rows,fmap):
    if 'quantifier' in a:
        vals=[indep_cmp(a['predicate'],rows,o,fmap) for o in range(a['from'],a['to']+1)]
        return any(vals) if a['quantifier']=='any' else all(vals)
    return indep_cmp(a,rows,None,fmap)

r=random.Random(7)
nf=3
fmap={}
schema=[]
for i in range(nf):
    schema.append(('n%d'%i,'SIZE',0,100))
for i,(n,t,lo,hi) in enumerate(schema):
    fmap[n]={'index':i,'type':t,'min':lo,'max':hi}
nchecks=0
for _ in range(2000):
    K=r.randint(1,4)
    rows=[[r.randint(0,100) for _ in range(nf)] for _ in range(K)]
    def mkterm(depth=1):
        choices=['field','const','agg']
        if depth<4: choices+=['scale','add']
        c=r.choice(choices)
        if c=='field':
            return {'field':'n%d'%r.randrange(nf),'at':(r.choice(['$',r.randrange(K)]) if depth>1 else r.randrange(K))}
        if c=='const':
            return {'const':r.randint(-50,150),'type':'SIZE'}
        if c=='agg':
            a=r.randrange(K); b=r.randint(a,K-1)
            return {'aggregate':r.choice(['sum','mean','min','max']),'field':'n%d'%r.randrange(nf),'from':a,'to':b}
        if c=='scale':
            return {'scale':r.randint(-3,3),'term':mkterm(depth+1)}
        return {'add':[mkterm(depth+1),mkterm(depth+1)]}
    # build comparison
    left=mkterm(); 
    # make right same type SIZE
    right=mkterm()
    comp={'cmp':r.choice(['eq','ne','lt','le','gt','ge']),'left':left,'right':right}
    if r.random()<0.4:
        a=r.randrange(K); b=r.randint(a,K-1)
        atom={'quantifier':r.choice(['any','all']),'from':a,'to':b,'predicate':comp}
    else:
        atom=comp
    try:
        v1=main.eval_atom(atom,rows,fmap)
    except Exception as e:
        continue
    v2=indep_atom(atom,rows,fmap)
    nchecks+=1
    if v1!=v2:
        print('MISMATCH',atom,rows,v1,v2); break
print('checks',nchecks)
